@theme {
  --color-srf-rose: #F3E8E4;
  --color-srf-oxblood: #4B202A;
  --color-srf-clay: #9A463D;
  --color-srf-mauve: #735B60;
  --color-srf-flax: #D8C4A7;
  --color-srf-sage: #A6B3A0;
  --color-srf-porcelain: #FFFCF8;

  --font-display: var(--font-anybody), "Anybody", system-ui, -apple-system, sans-serif;
  --font-body: var(--font-commissioner), "Commissioner", system-ui, -apple-system, sans-serif;
  --font-mono: var(--font-victor-mono), "Victor Mono", ui-monospace, SFMono-Regular, monospace;

  --ease-out: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);

  --dur-instant: 90ms;
  --dur-fast: 180ms;
  --dur-base: 420ms;
  --dur-slow: 700ms;
  --dur-hero: 1000ms;
  --stagger: 60ms;
  --reveal-shift: 24px;
}

:root {
  --srf-rose: #F3E8E4;
  --srf-oxblood: #4B202A;
  --srf-clay: #9A463D;
  --srf-mauve: #735B60;
  --srf-flax: #D8C4A7;
  --srf-sage: #A6B3A0;
  --srf-porcelain: #FFFCF8;
  --srf-hairline: color-mix(in srgb, #4B202A 18%, #F3E8E4);
  --srf-hairline-strong: color-mix(in srgb, #4B202A 32%, #F3E8E4);
  --srf-hairline-dark: color-mix(in srgb, #FFFCF8 22%, #4B202A);
  --srf-surface-soft: color-mix(in srgb, #FFFCF8 58%, #F3E8E4);
  --srf-shadow: color-mix(in srgb, #4B202A 12%, transparent);
}

html {
  background-color: var(--srf-rose);
  color: var(--srf-oxblood);
  font-family: var(--font-body);
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
}

body {
  margin: 0;
  background-color: var(--srf-rose);
  color: var(--srf-oxblood);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 24px;
  overflow-x: clip;
}

@media (min-width: 900px) {
  body {
    font-size: 18px;
    line-height: 28px;
  }
}

/* Global accessible focus */
:focus-visible {
  outline: 2px solid var(--srf-oxblood);
  outline-offset: 4px;
}

.srf-dark-surface :focus-visible {
  outline-color: var(--srf-porcelain);
}

/* Skip link */
.srf-skip-link {
  position: absolute;
  left: -9999px;
  top: 12px;
  z-index: 100;
  background: var(--srf-oxblood);
  color: var(--srf-porcelain);
  padding: 10px 16px;
  border-radius: 8px;
  font-size: 14px;
  font-weight: 500;
  text-decoration: none;
}

.srf-skip-link:focus {
  left: 16px;
}

/* Editorial container */
.srf-container {
  width: 100%;
  max-width: 1600px;
  margin-inline: auto;
  padding-inline: 20px;
}

@media (min-width: 640px) {
  .srf-container {
    padding-inline: 32px;
  }
}

@media (min-width: 1024px) {
  .srf-container {
    padding-inline: 48px;
  }
}

/* Typography roles */
.srf-h1 {
  font-family: var(--font-display);
  font-weight: 600;
  font-size: clamp(44px, 5.6vw, 80px);
  line-height: 1.02;
  letter-spacing: -0.035em;
  color: var(--srf-oxblood);
}

.srf-h1-studio {
  font-family: var(--font-display);
  font-weight: 600;
  font-size: clamp(38px, 4.4vw, 66px);
  line-height: 1.03;
  letter-spacing: -0.035em;
  color: var(--srf-oxblood);
}

/* Mobile sticky studio stage below 64px header (disabled on short landscape), static on tablet, sticky 60% stage on desktop */
.srf-studio-stage-wrap {
  position: sticky;
  top: 64px;
  z-index: 25;
  height: 218px;
  background-color: var(--srf-rose);
  padding-top: 4px;
  padding-bottom: 10px;
}

@media (max-width: 639px) {
  .srf-studio-stage-wrap > div {
    box-shadow: 0 8px 18px -10px color-mix(in srgb, #4B202A 22%, transparent);
  }
}

@media (max-height: 580px) {
  .srf-studio-stage-wrap {
    position: static;
    height: 236px;
    padding-bottom: 0;
  }
}

@media (min-width: 640px) {
  .srf-studio-stage-wrap {
    position: static;
    height: 380px;
    padding-bottom: 0;
  }
}

@media (min-width: 1024px) {
  .srf-studio-stage-wrap {
    position: sticky;
    top: 96px;
    z-index: 10;
    height: min(680px, calc(100svh - 120px));
    min-height: 460px;
    padding-bottom: 0;
  }
}

.srf-h2 {
  font-family: var(--font-display);
  font-weight: 600;
  font-size: clamp(32px, 4vw, 60px);
  line-height: 1.08;
  letter-spacing: -0.025em;
}

.srf-h3 {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: clamp(22px, 2.2vw, 30px);
  line-height: 1.18;
  letter-spacing: -0.02em;
}

.srf-mono-caption {
  font-family: var(--font-mono);
  font-size: 12px;
  line-height: 18px;
  font-weight: 400;
  font-variant-numeric: tabular-nums;
}

.srf-mono-dim {
  font-family: var(--font-mono);
  font-size: 14px;
  line-height: 20px;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
}

/* Primary & secondary buttons */
.srf-btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 48px;
  padding: 12px 20px;
  border-radius: 8px;
  background-color: var(--srf-clay);
  color: var(--srf-porcelain);
  font-family: var(--font-body);
  font-size: 16px;
  font-weight: 500;
  line-height: 24px;
  text-decoration: none;
  white-space: nowrap;
  cursor: pointer;
  border: 1px solid transparent;
  transition:
    background-color var(--dur-fast) var(--ease-out),
    transform var(--dur-instant) var(--ease-out);
}

.srf-btn-primary:hover:not(:disabled) {
  background-color: color-mix(in srgb, var(--srf-clay) 86%, var(--srf-oxblood));
}

.srf-btn-primary:active:not(:disabled) {
  transform: scale(0.98);
}

.srf-btn-primary:disabled {
  opacity: 0.65;
  cursor: not-allowed;
}

.srf-btn-primary .srf-btn-arrow {
  transition: transform var(--dur-fast) var(--ease-out);
}

.srf-btn-primary:hover:not(:disabled) .srf-btn-arrow {
  transform: translateX(4px);
}

.srf-btn-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 44px;
  padding: 10px 16px;
  border-radius: 8px;
  border: 1px solid var(--srf-hairline-strong);
  background-color: transparent;
  color: var(--srf-oxblood);
  font-family: var(--font-body);
  font-size: 15px;
  font-weight: 500;
  line-height: 22px;
  white-space: nowrap;
  cursor: pointer;
  transition:
    background-color var(--dur-fast) var(--ease-out),
    border-color var(--dur-fast) var(--ease-out),
    transform var(--dur-instant) var(--ease-out);
}

.srf-btn-secondary:hover:not(:disabled) {
  background-color: color-mix(in srgb, var(--srf-oxblood) 6%, transparent);
  border-color: var(--srf-oxblood);
}

.srf-btn-secondary:active:not(:disabled) {
  transform: scale(0.98);
}

.srf-btn-secondary[aria-pressed="true"],
.srf-btn-secondary[aria-pressed="true"]:hover:not(:disabled) {
  background-color: var(--srf-oxblood);
  color: var(--srf-porcelain);
  border-color: var(--srf-oxblood);
}

.srf-text-link {
  position: relative;
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  font-size: 16px;
  font-weight: 500;
  color: var(--srf-oxblood);
  text-decoration: none;
  white-space: nowrap;
}

.srf-text-link::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 9px;
  height: 1px;
  background-color: currentColor;
  transform: scaleX(0.45);
  transform-origin: left;
  transition: transform var(--dur-fast) var(--ease-out);
}

.srf-text-link:hover::after,
.srf-text-link:focus-visible::after {
  transform: scaleX(1);
}

/* Native range input styled cleanly for Rose/Oxblood/Clay */
.srf-range {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 44px;
  background: transparent;
  cursor: pointer;
}

.srf-range::-webkit-slider-runnable-track {
  height: 4px;
  border-radius: 2px;
  background: var(--srf-hairline-strong);
}

.srf-range::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 24px;
  height: 24px;
  margin-top: -10px;
  border-radius: 9999px;
  background: var(--srf-clay);
  border: 2px solid var(--srf-porcelain);
  box-shadow: 0 2px 6px var(--srf-shadow);
  transition: transform var(--dur-fast) var(--ease-out), background-color var(--dur-fast) var(--ease-out);
}

.srf-range:hover::-webkit-slider-thumb {
  transform: scale(1.08);
}

.srf-range::-moz-range-track {
  height: 4px;
  border-radius: 2px;
  background: var(--srf-hairline-strong);
}

.srf-range::-moz-range-thumb {
  width: 24px;
  height: 24px;
  border-radius: 9999px;
  background: var(--srf-clay);
  border: 2px solid var(--srf-porcelain);
  box-shadow: 0 2px 6px var(--srf-shadow);
}

/* Folded corner receipt motif */
.srf-receipt-card {
  position: relative;
  background-color: var(--srf-porcelain);
  border: 1px solid var(--srf-hairline-strong);
  border-radius: 8px;
  clip-path: polygon(0 0, calc(100% - 28px) 0, 100% 28px, 100% 100%, 0 100%);
}

.srf-receipt-corner {
  position: absolute;
  top: 0;
  right: 0;
  width: 28px;
  height: 28px;
  background-color: color-mix(in srgb, var(--srf-sage) 42%, var(--srf-rose));
  clip-path: polygon(0 0, 0 100%, 100% 100%);
  pointer-events: none;
}

/* Native details FAQ styling */
.srf-faq-item {
  border-top: 1px solid var(--srf-hairline);
}

.srf-faq-item:last-child {
  border-bottom: 1px solid var(--srf-hairline);
}

.srf-faq-summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  min-height: 64px;
  padding-block: 18px;
  font-family: var(--font-body);
  font-size: 18px;
  line-height: 26px;
  font-weight: 500;
  color: var(--srf-oxblood);
  cursor: pointer;
  list-style: none;
}

.srf-faq-summary::-webkit-details-marker {
  display: none;
}

.srf-faq-icon {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  transition: transform var(--dur-fast) var(--ease-out);
}

details[open] .srf-faq-icon {
  transform: rotate(45deg);
}

.srf-faq-answer {
  padding-bottom: 22px;
  max-width: 60ch;
  color: var(--srf-mauve);
  font-size: 16px;
  line-height: 26px;
}

.srf-faq-panel {
  overflow: hidden;
}

details[data-closing] .srf-faq-icon {
  transform: none;
}

.srf-faq-icon {
  transition: transform 520ms var(--ease-out-expo);
}

/* Studio lighting backdrop & Hero entrance sequence (compositor only, honors reduced motion) */
.srf-studio-glow {
  background: radial-gradient(
    ellipse 68% 72% at 64% 44%,
    color-mix(in srgb, #FFFCF8 38%, transparent) 0%,
    color-mix(in srgb, #FFFCF8 12%, transparent) 46%,
    transparent 76%
  );
}

@media (prefers-reduced-motion: no-preference) {
  @keyframes srf-studio-veil {
    from {
      opacity: 0;
    }
    to {
      opacity: 1;
    }
  }

  @keyframes srf-draw-arc {
    from {
      stroke-dashoffset: 68;
    }
    to {
      stroke-dashoffset: 0;
    }
  }

  .srf-studio-glow {
    animation: srf-studio-veil 420ms var(--ease-out) 0ms both;
  }

  /* Entrance targets wait for the anime.js timeline. If scripting never arrives, the
     failsafe reveals them so the hero is never left blank. */
  @keyframes srf-hm-failsafe {
    to {
      opacity: 1;
    }
  }

  .srf-hero-section:is([data-hero-motion='pending'], [data-hero-motion='run']) :is(
    [data-hm='eyebrow'],
    [data-hm='rule'],
    [data-hm='char'],
    [data-hm='lead'],
    [data-hm='cta'],
    [data-hm='dock'],
    [data-hm='chip']
  ) {
    opacity: 0;
  }

  .srf-hero-section[data-hero-motion='pending'] [data-hm] {
    animation: srf-hm-failsafe 1ms linear 3400ms forwards;
  }

  .srf-drag-arc path {
    stroke-dasharray: 68;
    animation: srf-draw-arc 780ms var(--ease-out-expo) 1300ms both;
  }
}

/* Hero motion hooks (driven by motion/useHeroMotion.ts) */
.srf-hm-wordbox {
  display: inline-block;
  perspective: 700px;
  white-space: nowrap;
}

.srf-hm-char {
  display: inline-block;
  transform-origin: 50% 100%;
  backface-visibility: hidden;
}

.srf-hero-section [data-hm='dock-group'] {
  transform-origin: 50% 0%;
}

.srf-hm-rule {
  display: block;
  width: 44px;
  height: 1px;
  background: var(--room-ui-accent);
  transform-origin: 0% 50%;
}

.srf-hero-section [data-hm='chip'] {
  position: relative;
}

.srf-hm-ripple {
  position: absolute;
  inset: -2px;
  border: 1.5px solid var(--room-ui-outline);
  pointer-events: none;
}

/* ============================================================================
   Page motion system (driven by motion/usePageMotion.ts)
   ============================================================================ */

/* Anything waiting for its scroll-in stays hidden only once scripting has taken over */
.srf-motion-ready [data-m]:not([data-m-in]) {
  opacity: 0;
}

[data-m='rule'] {
  transform-origin: 0% 50%;
}

[data-hinge],
[data-base] {
  transform-box: fill-box;
  transform-origin: center;
}

/* --- Opening pleat curtain --- */
.srf-curtain {
  display: none;
}

@media (prefers-reduced-motion: no-preference) {
  @keyframes srf-curtain-failsafe {
    to {
      visibility: hidden;
    }
  }

  .srf-curtain {
    position: fixed;
    inset: 0;
    z-index: 90;
    display: block;
    pointer-events: none;
    color: var(--srf-flax);
  }

  .srf-curtain[data-curtain=''] {
    animation: srf-curtain-failsafe 1ms linear 4200ms forwards;
  }

  .srf-curtain[data-curtain='done'] {
    display: none;
  }

  .srf-curtain-panels {
    position: absolute;
    inset: 0;
    display: flex;
  }

  .srf-curtain-panel {
    flex: 1 1 0;
    /* 1px overlap hides hairline seams between panels */
    margin-inline: -0.5px;
    background: linear-gradient(90deg, #3D1821 0%, #4B202A 55%, #57262F 100%);
    transform-origin: 0% 50%;
    will-change: transform;
  }

  .srf-curtain-panel:nth-child(even) {
    background: linear-gradient(90deg, #57262F 0%, #4B202A 45%, #3D1821 100%);
    transform-origin: 100% 50%;
  }

  .srf-curtain-core {
    position: absolute;
    inset: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 18px;
  }

  .srf-curtain-zig {
    width: min(420px, 62vw);
    height: auto;
  }

  .srf-curtain-word {
    font-family: var(--font-display);
    font-weight: 600;
    font-size: clamp(34px, 6.4vw, 88px);
    line-height: 1;
    font-stretch: 50%;
    color: var(--srf-porcelain);
    white-space: nowrap;
  }

  .srf-curtain-meta {
    font-family: var(--font-mono);
    font-size: 12px;
    letter-spacing: 0.14em;
    font-variant-numeric: tabular-nums;
    color: var(--srf-flax);
  }
}

/* --- Header crease (page progress) --- */
.srf-crease {
  position: absolute;
  left: 0;
  bottom: -3px;
  width: 100%;
  height: 6px;
  color: var(--srf-clay);
  transform-origin: 0% 50%;
  pointer-events: none;
  display: none;
}

.srf-motion-ready .srf-crease {
  display: block;
}

.srf-logo-word {
  font-stretch: 100%;
  transition: font-stretch 520ms var(--ease-out-expo), letter-spacing 520ms var(--ease-out-expo);
}

.srf-logo-link:hover .srf-logo-word {
  font-stretch: 150%;
}

/* --- Velocity ticker --- */
.srf-ticker {
  overflow: hidden;
  padding-block: 18px;
  background: var(--srf-oxblood);
  color: var(--srf-rose);
  border-bottom: 1px solid var(--srf-hairline);
}

.srf-ticker-track {
  display: flex;
  width: max-content;
  will-change: transform;
}

.srf-ticker-set {
  display: flex;
  align-items: center;
  gap: clamp(20px, 3vw, 44px);
  padding-right: clamp(20px, 3vw, 44px);
}

.srf-ticker-word {
  font-family: var(--font-display);
  font-weight: 600;
  font-stretch: 125%;
  font-size: clamp(30px, 4.6vw, 68px);
  line-height: 1;
  letter-spacing: -0.02em;
  text-transform: uppercase;
  white-space: nowrap;
}

.srf-ticker-outline {
  color: transparent;
  -webkit-text-stroke: 1.2px var(--srf-flax);
  font-stretch: 62%;
}

.srf-ticker-zig {
  width: clamp(34px, 4vw, 56px);
  height: auto;
  flex-shrink: 0;
  color: var(--srf-clay);
}

/* --- Pleat ruler --- */
.srf-ruler {
  display: grid;
  grid-template-columns: repeat(16, minmax(0, 1fr));
  align-items: end;
  height: 46px;
  max-width: 660px;
  border-bottom: 1px solid var(--srf-hairline-strong);
}

.srf-ruler-tick {
  position: relative;
  display: block;
  height: 14px;
  border-left: 1px solid var(--srf-hairline-strong);
  transform-origin: 50% 100%;
}

.srf-ruler-tick:nth-child(4n + 1) {
  height: 26px;
  border-left-color: var(--srf-oxblood);
}

.srf-ruler-tick i {
  display: none;
  position: absolute;
  left: 5px;
  top: -4px;
  font-family: var(--font-mono);
  font-style: normal;
  font-size: 10px;
  line-height: 1;
  color: var(--srf-mauve);
}

.srf-ruler-tick:nth-child(4n + 1) i {
  display: block;
}

/* --- Construction: pleated top edge + spec rules --- */
.srf-teeth {
  position: absolute;
  top: -1px;
  left: 0;
  width: 100%;
  height: clamp(28px, 4.5vw, 64px);
  transform-origin: 50% 0%;
  pointer-events: none;
  display: none;
}

.srf-motion-ready .srf-teeth {
  display: block;
}

.srf-spec-rule {
  display: block;
  height: 1px;
  margin-bottom: 12px;
  background: var(--srf-hairline-dark);
}

/* --- Footer wordmark --- */
.srf-wordmark-wrap {
  overflow: hidden;
  margin-bottom: 28px;
  padding-bottom: 0.04em;
}

.srf-wordmark {
  width: max-content;
  font-family: var(--font-display);
  font-weight: 600;
  font-size: 13vw;
  font-stretch: 112%;
  line-height: 0.86;
  letter-spacing: -0.03em;
  white-space: nowrap;
  color: var(--srf-oxblood);
  cursor: default;
  user-select: none;
}

.srf-wordmark span {
  display: inline-block;
}

/* ============================================================================
   SERRAFORM — The Living Room Atelier (Coded 2.5D Architectural Backdrop)
   ============================================================================ */

.srf-hero-section {
  position: relative;
  min-height: calc(100vh - 4rem);
  min-height: calc(100svh - 4rem);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  --room-wall-base: #F4EAE4;
  --room-wall-highlight: #FAF4F0;
  --room-wall-shadow: #E4CFC7;
  --room-floor-base: #DEC6BC;
  --room-floor-far: #EBD8D0;
  --room-floor-detail: #C5A89D;
  --room-rug: #FAF3EE;
  --room-rug-trim: #7B4A4D;
  --room-textile-primary: #ECE0DA;
  --room-textile-secondary: #E3D3CC;
  --room-furniture: #D8C4A7;
  --room-furniture-leg: #7C5B53;
  --room-decor-primary: #7B4A4D;
  --room-decor-accent: #9A463D;
  --room-trim: #9A463D;
  --room-foliage: #7F8E77;
  --room-light-tint: #FFF8F0;
  --room-ambient-tint: #EBD8D0;
  --room-shadow-tint: #4B202A;
  --room-quiet-bg: #F8F0EC;
  --room-ui-accent: #9A463D;
  --room-ui-accent-hover: #7D362E;
  --room-ui-accent-text: #FFFCF8;
  --room-ui-outline: #4B202A;
